'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import {
  FileSpreadsheetIcon,
  FileTextIcon,
  ImageIcon,
  LoaderCircleIcon,
  PaperclipIcon,
  XIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { draftCommentOf, type CommentItem } from './_parts/comment-model';
import { CommentBlock, CommentText } from './_parts/comment-parts';
import { ENTER, EXIT, heightPresenceOf, Swap } from './_parts/motion-parts';

type FileKind = 'image' | 'sheet' | 'document';

type AttachedFile = {
  id: string;
  name: string;
  size: number;
  kind: FileKind;
  previewSrc?: string;
};

type StagedFile = AttachedFile & {
  isReady: boolean;
};

type AttachedComment = CommentItem & {
  files: AttachedFile[];
};

const MAX_FILE_BYTES = 10 * 1024 * 1024;

const UPLOAD_MS = 900;

const ACCEPTED_TYPES = 'image/*,.pdf,.csv,.txt';

const KIND_ICON: Record<FileKind, Icon> = {
  image: ImageIcon,
  sheet: FileSpreadsheetIcon,
  document: FileTextIcon,
};

const FIRST_COMMENTS: AttachedComment[] = [
  {
    id: 'a1',
    authorId: 'mei',
    at: '2026-11-05T09:52:00',
    body: 'Here is the sample finance sent, and how it looks once opened in the ledger.',
    files: [
      {
        id: 'f1',
        name: 'ledger-preview.svg',
        size: 412_000,
        kind: 'image',
        previewSrc: '/images/scenes/scene-03.svg',
      },
      {
        id: 'f2',
        name: 'invoices-october.csv',
        size: 18_400,
        kind: 'sheet',
      },
    ],
  },
];

const CHIP_MOTION: MotionProps = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.95, transition: EXIT },
  transition: ENTER,
};

const CHIP_FADE: MotionProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

function chipMotionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  return CHIP_MOTION;
}

function layoutOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return false;
  }
  return 'position';
}

function sizeLabelOf(bytes: number) {
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  const kilobytes = bytes / 1024;
  if (kilobytes < 1024) {
    return `${Math.round(kilobytes)} KB`;
  }
  const megabytes = kilobytes / 1024;
  return `${megabytes.toFixed(1)} MB`;
}

function kindOf(file: File): FileKind {
  if (file.type.startsWith('image/')) {
    return 'image';
  }
  const isSheet = file.name.toLowerCase().endsWith('.csv');
  if (isSheet) {
    return 'sheet';
  }
  return 'document';
}

function isAccepted(file: File) {
  const name = file.name.toLowerCase();
  const isImage = file.type.startsWith('image/');
  const isPdf = name.endsWith('.pdf');
  const isCsv = name.endsWith('.csv');
  const isText = name.endsWith('.txt');
  return [isImage, isPdf, isCsv, isText].some(Boolean);
}

function refusalOf(file: File) {
  if (!isAccepted(file)) {
    return `“${file.name}” can’t be attached. Pick an image, a PDF, a CSV or a text file`;
  }
  if (file.size > MAX_FILE_BYTES) {
    return `“${file.name}” is over 10 MB. Attach a smaller file`;
  }
  return null;
}

let stagedCount = 0;

function stagedFileOf(file: File): StagedFile {
  stagedCount += 1;
  return {
    id: `staged-${stagedCount}`,
    name: file.name,
    size: file.size,
    kind: kindOf(file),
    isReady: false,
  };
}

function withReady(files: StagedFile[], fileId: string) {
  return files.map((file) => {
    if (file.id !== fileId) {
      return file;
    }
    return { ...file, isReady: true };
  });
}

function stateKeyOf(isReady: boolean) {
  if (isReady) {
    return 'ready';
  }
  return 'uploading';
}

function FileTile({ file }: { file: AttachedFile }) {
  const Glyph = KIND_ICON[file.kind];
  return (
    <li className='bg-card hairline-ring ring-border flex w-44 flex-col overflow-hidden rounded-lg'>
      {file.previewSrc && (
        // eslint-disable-next-line @next/next/no-img-element -- registry items land in any React app, where next/image may not exist
        <img
          src={file.previewSrc}
          alt=''
          className='bg-muted aspect-[16/9] w-full object-cover'
        />
      )}
      <span className='flex items-center gap-2 px-2.5 py-2'>
        <Glyph className='text-muted-foreground size-4 shrink-0' />
        <span className='min-w-0 flex-1'>
          <span className='block truncate text-xs font-medium'>
            {file.name}
          </span>
          <span className='text-muted-foreground block text-[11px] tabular-nums'>
            {sizeLabelOf(file.size)}
          </span>
        </span>
      </span>
    </li>
  );
}

function PostedComment({ comment }: { comment: AttachedComment }) {
  const shouldReduceMotion = useReducedMotion();
  const hasFiles = comment.files.length > 0;
  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <CommentBlock comment={comment} className='pb-4'>
        <CommentText body={comment.body} />
        {hasFiles && (
          <ul aria-label='Attachments' className='mt-2 flex flex-wrap gap-2'>
            {comment.files.map((file) => (
              <FileTile key={file.id} file={file} />
            ))}
          </ul>
        )}
      </CommentBlock>
    </motion.li>
  );
}

function StagedChip({
  file,
  onRemove,
}: {
  file: StagedFile;
  onRemove: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const Glyph = KIND_ICON[file.kind];

  return (
    <motion.li
      layout={layoutOf(shouldReduceMotion)}
      {...chipMotionOf(shouldReduceMotion)}
      className='bg-foreground/[0.04] flex h-7 max-w-52 items-center gap-1.5 rounded-md ps-2 pe-0.5 text-xs'
    >
      <Swap swapKey={stateKeyOf(file.isReady)}>
        {!file.isReady && (
          <LoaderCircleIcon className='text-muted-foreground size-3.5 animate-spin' />
        )}
        {file.isReady && <Glyph className='text-muted-foreground size-3.5' />}
      </Swap>
      <span className='min-w-0 truncate font-medium'>{file.name}</span>
      <span className='text-muted-foreground shrink-0 tabular-nums'>
        {sizeLabelOf(file.size)}
      </span>
      <button
        type='button'
        onClick={onRemove}
        aria-label={`Remove ${file.name}`}
        className='text-muted-foreground hover:bg-foreground/5 hover:text-foreground focus-visible:ring-ring/25 inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]'
      >
        <XIcon className='size-3' />
      </button>
    </motion.li>
  );
}

export default function Comment06() {
  const shouldReduceMotion = useReducedMotion();
  const [comments, setComments] = useState(FIRST_COMMENTS);
  const [body, setBody] = useState('');
  const [staged, setStaged] = useState<StagedFile[]>([]);
  const [refusal, setRefusal] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const trimmed = body.trim();
  const hasStaged = staged.length > 0;
  const isUploading = staged.some((file) => !file.isReady);
  const hasContent = trimmed.length > 0 || hasStaged;
  const canSend = hasContent && !isUploading;

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function finishUpload(fileId: string) {
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      setStaged((current) => withReady(current, fileId));
    }, UPLOAD_MS);
    timers.current.add(timer);
  }

  function stage(event: React.ChangeEvent<HTMLInputElement>) {
    const picked = Array.from(event.target.files ?? []);
    event.target.value = '';
    const refusals = picked.map(refusalOf);
    const firstRefusal = refusals.find((message) => message !== null);
    setRefusal(firstRefusal ?? null);
    const accepted = picked.filter((file) => refusalOf(file) === null);
    const added = accepted.map(stagedFileOf);
    setStaged((current) => [...current, ...added]);
    added.forEach((file) => finishUpload(file.id));
  }

  function unstage(fileId: string) {
    setStaged((current) => current.filter((file) => file.id !== fileId));
  }

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSend) {
      return;
    }
    const files: AttachedFile[] = staged.map((file) => ({
      id: file.id,
      name: file.name,
      size: file.size,
      kind: file.kind,
    }));
    const comment: AttachedComment = { ...draftCommentOf(trimmed), files };
    setComments((current) => [...current, comment]);
    setBody('');
    setStaged([]);
    setRefusal(null);
  }

  return (
    <section aria-label='Comments with files' className='w-full max-w-md'>
      <ul>
        <AnimatePresence initial={false}>
          {comments.map((comment) => (
            <PostedComment key={comment.id} comment={comment} />
          ))}
        </AnimatePresence>
      </ul>
      <form
        onSubmit={send}
        className='bg-card hairline-ring ring-foreground/12 focus-within:ring-ring/25 dark:bg-foreground/[0.04] dark:ring-foreground/15 rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.05)] focus-within:ring-[3px]'
      >
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          rows={2}
          aria-label='Comment'
          placeholder='Add a comment or attach a file'
          className='min-h-14 border-0 bg-transparent shadow-none ring-0 focus-visible:border-transparent focus-visible:ring-0 dark:bg-transparent'
        />
        <ul aria-label='Files to attach' className='flex flex-wrap gap-1 px-2'>
          <AnimatePresence initial={false} mode='popLayout'>
            {staged.map((file) => (
              <StagedChip
                key={file.id}
                file={file}
                onRemove={() => unstage(file.id)}
              />
            ))}
          </AnimatePresence>
        </ul>
        <div className='flex items-center justify-between px-1.5 py-1.5'>
          <input
            ref={inputRef}
            type='file'
            multiple
            accept={ACCEPTED_TYPES}
            onChange={stage}
            className='sr-only'
            tabIndex={-1}
            aria-hidden='true'
          />
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label='Attach files'
            onClick={() => inputRef.current?.click()}
            className='text-muted-foreground'
          >
            <PaperclipIcon />
          </Button>
          <Button type='submit' size='sm' disabled={!canSend}>
            Comment
          </Button>
        </div>
      </form>
      <AnimatePresence initial={false}>
        {refusal && (
          <motion.p
            key='refusal'
            role='alert'
            {...heightPresenceOf(shouldReduceMotion)}
            className='text-destructive-ink overflow-hidden text-xs'
          >
            <span className='block pt-2'>{refusal}</span>
          </motion.p>
        )}
      </AnimatePresence>
    </section>
  );
}

import { CURRENT_USER_ID, PEOPLE } from './people';
import { NOW } from './time';

export type CommentItem = {
  id: string;
  authorId: string;
  at: string;
  body: string;
  editedAt?: string;
};

export type Segment = {
  text: string;
  isMention: boolean;
};

export const MENTION_TRIGGER = '@';

export const MENTION_NAMES = PEOPLE.map((person) => person.name);

function mentionTokensOf(names: string[]) {
  const tokens = names.map((name) => `${MENTION_TRIGGER}${name}`);
  return tokens.sort((first, second) => second.length - first.length);
}

function pushPlain(segments: Segment[], text: string) {
  if (text.length === 0) {
    return;
  }
  segments.push({ text, isMention: false });
}

/** Splits a comment into plain text and mentions of known people, written "@First Last". */
export function segmentsOf(text: string, names: string[] = MENTION_NAMES) {
  const tokens = mentionTokensOf(names);
  const segments: Segment[] = [];
  let plain = '';
  let index = 0;
  while (index < text.length) {
    const token = tokens.find((candidate) => text.startsWith(candidate, index));
    if (token) {
      pushPlain(segments, plain);
      segments.push({ text: token, isMention: true });
      plain = '';
      index += token.length;
      continue;
    }
    plain += text[index];
    index += 1;
  }
  pushPlain(segments, plain);
  return segments;
}

let draftCount = 0;

/** A comment the signed-in person just wrote, stamped with the previews' fixed now. */
export function draftCommentOf(body: string): CommentItem {
  draftCount += 1;
  return {
    id: `draft-${draftCount}`,
    authorId: CURRENT_USER_ID,
    at: NOW,
    body,
  };
}

export function commentWordOf(count: number) {
  if (count === 1) {
    return 'comment';
  }
  return 'comments';
}

export function replyWordOf(count: number) {
  if (count === 1) {
    return 'reply';
  }
  return 'replies';
}

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import { segmentsOf, type CommentItem } from './comment-model';
import { actorNameOf, personOf, type Person } from './people';
import { relativeTimeOf } from './time';

export const MENTION_CHIP =
  'rounded-[4px] bg-primary/10 px-0.5 font-medium text-primary-ink dark:bg-primary/20';

export const TEXT_ACTION =
  'text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 inline-flex h-6 cursor-pointer items-center gap-1 rounded-md text-xs font-medium transition-colors outline-none focus-visible:ring-[3px]';

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-7 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

/** A comment's words, with each mention of a known person drawn as a tinted chip. */
export function CommentText({
  body,
  className,
}: {
  body: string;
  className?: string;
}) {
  const segments = segmentsOf(body);
  return (
    <p
      className={cn(
        'text-[13px] leading-5 [overflow-wrap:anywhere] whitespace-pre-wrap',
        className
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <span key={key} className={MENTION_CHIP}>
              {segment.text}
            </span>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
    </p>
  );
}

export function CommentMeta({
  comment,
  children,
}: {
  comment: CommentItem;
  children?: React.ReactNode;
}) {
  return (
    <p className='flex min-w-0 items-baseline gap-1.5 text-[13px]'>
      <span className='truncate font-medium'>
        {actorNameOf(comment.authorId)}
      </span>
      <span aria-hidden='true' className='text-muted-foreground'>
        ·
      </span>
      <time
        dateTime={comment.at}
        className='text-muted-foreground shrink-0 text-xs tabular-nums'
      >
        {relativeTimeOf(comment.at)}
      </time>
      {children}
    </p>
  );
}

type CommentBlockProps = {
  comment: CommentItem;
  avatarClassName?: string;
  meta?: React.ReactNode;
  actions?: React.ReactNode;
  children?: React.ReactNode;
  className?: string;
};

/** Avatar, author and time, then the words aligned under the name. */
export function CommentBlock({
  comment,
  avatarClassName,
  meta,
  actions,
  children,
  className,
}: CommentBlockProps) {
  return (
    <div className={cn('flex gap-3', className)}>
      <PersonAvatar
        person={personOf(comment.authorId)}
        className={avatarClassName}
      />
      <div className='min-w-0 flex-1'>
        <div className='flex min-h-7 items-center justify-between gap-2'>
          <CommentMeta comment={comment}>{meta}</CommentMeta>
          {actions}
        </div>
        {children}
        {!children && <CommentText body={comment.body} />}
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export type Person = {
  id: string;
  name: string;
  firstName: string;
  initials: string;
  avatar?: string;
};

export const CURRENT_USER_ID = 'amara';

export const PEOPLE: Person[] = [
  {
    id: 'amara',
    name: 'Amara Okafor',
    firstName: 'Amara',
    initials: 'AO',
    avatar: '/avatars/avatar-03.svg',
  },
  {
    id: 'leo',
    name: 'Léo Martin',
    firstName: 'Léo',
    initials: 'LM',
    avatar: '/avatars/avatar-04.svg',
  },
  {
    id: 'sana',
    name: 'Sana Iqbal',
    firstName: 'Sana',
    initials: 'SI',
    avatar: '/avatars/avatar-05.svg',
  },
  {
    id: 'tomas',
    name: 'Tomás Rivera',
    firstName: 'Tomás',
    initials: 'TR',
    avatar: '/avatars/avatar-06.svg',
  },
  {
    id: 'mei',
    name: 'Mei Lin',
    firstName: 'Mei',
    initials: 'ML',
    avatar: '/avatars/avatar-07.svg',
  },
  {
    id: 'jonah',
    name: 'Jonah Brandt',
    firstName: 'Jonah',
    initials: 'JB',
  },
];

export function personOf(id: string) {
  const found = PEOPLE.find((person) => person.id === id);
  if (found) {
    return found;
  }
  return PEOPLE[0];
}

export function isCurrentUser(id: string) {
  return id === CURRENT_USER_ID;
}

export function actorNameOf(id: string) {
  if (isCurrentUser(id)) {
    return 'You';
  }
  return personOf(id).name;
}

export function currentUser() {
  return personOf(CURRENT_USER_ID);
}

import {
  differenceInCalendarDays,
  differenceInMinutes,
  format,
  parseISO,
} from 'date-fns';

/** The previews read every time against one fixed moment, so the server and the browser print the same labels. */
export const NOW = '2026-11-05T11:00:00';

const MINUTES_PER_HOUR = 60;

function daysBeforeNow(iso: string) {
  return differenceInCalendarDays(parseISO(NOW), parseISO(iso));
}

export function relativeTimeOf(iso: string) {
  const minutes = differenceInMinutes(parseISO(NOW), parseISO(iso));
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return `${minutes}m ago`;
  }
  const days = daysBeforeNow(iso);
  if (days === 0) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return `${hours}h ago`;
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'MMM d');
}

export function exactTimeOf(iso: string) {
  return format(parseISO(iso), "EEE, MMM d 'at' HH:mm");
}

export function clockOf(iso: string) {
  return format(parseISO(iso), 'HH:mm');
}

export function dayKeyOf(iso: string) {
  return iso.slice(0, 10);
}

export function dayLabelOf(iso: string) {
  const days = daysBeforeNow(iso);
  if (days === 0) {
    return 'Today';
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'EEEE, MMM d');
}

export function shortDateOf(iso: string) {
  return format(parseISO(iso), 'MMM d');
}

export function durationLabelOf(minutes: number) {
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const rest = minutes % MINUTES_PER_HOUR;
  if (hours === 0) {
    return `${rest}m`;
  }
  if (rest === 0) {
    return `${hours}h`;
  }
  return `${hours}h ${rest}m`;
}

export function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `${count} ${singular}`;
  }
  return `${count} ${plural}`;
}
